INSERT INTO assessment_questions (pillar, question_text, question_text_en, question_type, options, options_en, weight, sort_order) VALUES
('physical', '¿Con qué frecuencia haces ejercicio?', 'How often do you exercise?', 'single_choice', '["Nunca", "1-2 veces al mes", "1-2 veces por semana", "3-4 veces por semana", "5+ veces por semana"]', '["Never", "1-2 times a month", "1-2 times a week", "3-4 times a week", "5+ times a week"]', 3, 1),
('physical', '¿Qué tipo de ejercicio prefieres?', 'What type of exercise do you prefer?', 'multiple_choice', '["Gimnasio/Pesas", "Cardio (correr, nadar)", "Deportes de equipo", "Yoga/Pilates", "Calistenia", "Ninguno todavía"]', '["Gym/Weights", "Cardio (running, swimming)", "Team sports", "Yoga/Pilates", "Calisthenics", "None yet"]', 1, 2),
('physical', '¿Cómo calificarías tu alimentación actual?', 'How would you rate your current diet?', 'slider', null, null, 2, 3),
('physical', '¿Cuántas horas duermes en promedio por noche?', 'How many hours do you sleep on average per night?', 'single_choice', '["Menos de 5", "5-6 horas", "6-7 horas", "7-8 horas", "Más de 8"]', '["Less than 5", "5-6 hours", "6-7 hours", "7-8 hours", "More than 8"]', 2, 4),
('physical', '¿Cuántos vasos de agua bebes al día?', 'How many glasses of water do you drink per day?', 'single_choice', '["0-2", "3-4", "5-6", "7-8", "9+"]', '["0-2", "3-4", "5-6", "7-8", "9+"]', 1, 5),
('physical', '¿Cómo te sientes físicamente en general?', 'How do you feel physically overall?', 'slider', null, null, 2, 6),
('physical', '¿Cuáles son tus principales obstáculos para estar más activo?', 'What are your main obstacles to being more active?', 'multiple_choice', '["Falta de tiempo", "Falta de motivación", "No sé por dónde empezar", "Lesiones/dolor", "Costo de gimnasio", "Ninguno"]', '["Lack of time", "Lack of motivation", "Don''t know where to start", "Injuries/pain", "Gym cost", "None"]', 2, 7),
('physical', '¿Cómo calificarías tu rutina de cuidado personal?', 'How would you rate your personal care routine?', 'single_choice', '["No tengo rutina", "Básica (lo mínimo)", "Regular (ducha, dientes)", "Buena (incluyo skincare)", "Excelente (rutina completa)"]', '["No routine", "Basic (minimum)", "Regular (shower, teeth)", "Good (include skincare)", "Excellent (complete routine)"]', 2, 8),
('physical', '¿Qué aspectos te gustaría mejorar?', 'Which aspects would you like to improve?', 'multiple_choice', '["Cuidado de piel", "Cuidado del cabello", "Higiene dental", "Vestimenta", "Postura", "Hidratación", "Nada"]', '["Skin care", "Hair care", "Dental hygiene", "Clothing", "Posture", "Hydration", "Nothing"]', 1, 9),
('physical', '¿Con qué frecuencia cuidas tu apariencia?', 'How often do you take care of your appearance?', 'single_choice', '["Casi nunca", "Solo ocasiones especiales", "Algunas veces/semana", "Casi todos los días", "Todos los días"]', '["Almost never", "Special occasions only", "A few times a week", "Almost every day", "Every day"]', 2, 10);
