('mental', '¿Cómo calificarías tu concentración?', 'How would you rate your concentration?', 'slider', null, null, 2, 16),
('mental', '¿Qué te impide ser más productivo?', 'What prevents you from being more productive?', 'multiple_choice', '["Procrastinación", "Falta de objetivos", "Distracciones", "Cansancio mental", "Demasiadas tareas", "Nada"]', '["Procrastination", "Lack of goals", "Distractions", "Mental fatigue", "Too many tasks", "Nothing"]', 2, 17);
INSERT INTO assessment_questions (pillar, question_text, question_text_en, question_type, options, options_en, weight, sort_order) VALUES
