('social', '¿Cómo es tu relación con tu familia?', 'How is your relationship with your family?', 'single_choice', '["Muy distante", "Algo distante", "Normal", "Cercana", "Muy cercana"]', '["Very distant", "Somewhat distant", "Normal", "Close", "Very close"]', 1, 21),
('social', '¿Disfrutas conocer gente nueva?', 'Do you enjoy meeting new people?', 'single_choice', '["Para nada", "No mucho", "Indiferente", "Sí, me gusta", "Me encanta"]', '["Not at all", "Not much", "Indifferent", "Yes, I like it", "I love it"]', 1, 22),
('social', '¿En qué áreas sociales mejorarías?', 'In which social areas would you improve?', 'multiple_choice', '["Hacer amigos", "Mantener amistades", "Hablar en público", "Ser más sociable", "Networking", "Ninguna"]', '["Making friends", "Maintaining friendships", "Public speaking", "Being more sociable", "Networking", "None"]', 2, 23);
INSERT INTO assessment_questions (pillar, question_text, question_text_en, question_type, options, options_en, weight, sort_order) VALUES
