('professional', '¿Tienes sistema para gestionar finanzas?', 'Do you have a system to manage finances?', 'single_choice', '["No, ninguno", "Reviso ocasionalmente", "Sé cuánto gasto", "Presupuesto básico", "Presupuesto detallado"]', '["No, none", "Check occasionally", "Know how much I spend", "Basic budget", "Detailed budget"]', 2, 29),
('professional', '¿Qué te impide alcanzar tus metas?', 'What prevents you from reaching your goals?', 'multiple_choice', '["Falta experiencia", "Falta educación", "Falta oportunidades", "Miedo al fracaso", "No sé cómo empezar", "Nada"]', '["Lack experience", "Lack education", "Lack opportunities", "Fear of failure", "Don''t know how to start", "Nothing"]', 2, 30);
